<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $patient->full_name }} · CityCare</title><style>:root{--navy:#082f49;--blue:#2563eb;--cream:#f7fafc;--ink:#102a43;--muted:#627d98;--line:#d9e2ec;--green:#15803d}*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui;color:var(--ink);background:var(--cream)}main{max-width:1150px;margin:auto;padding:34px 22px}.top{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;margin-bottom:24px}.eyebrow{color:var(--blue);font-size:.74rem;font-weight:900;letter-spacing:.14em}h1{margin:6px 0;font-size:2.5rem;letter-spacing:-.05em}.muted{color:var(--muted);line-height:1.5}.panel{background:#fff;border:1px solid var(--line);border-radius:20px;padding:24px;margin-bottom:18px;box-shadow:0 8px 28px rgba(16,42,67,.05)}.hero{display:flex;justify-content:space-between;gap:20px;align-items:flex-start}.mrn{color:var(--blue);font-weight:900}.badge{padding:7px 10px;border-radius:999px;background:#ecfdf3;color:var(--green);font-size:.72rem;font-weight:900}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.item label{display:block;color:var(--muted);font-size:.72rem;font-weight:850;text-transform:uppercase;letter-spacing:.05em;margin-bottom:5px}.item strong{font-size:.98rem}.btn{display:inline-block;background:#eef2f7;color:var(--ink);padding:11px 15px;border-radius:10px;text-decoration:none;font-weight:850}@media(max-width:700px){.grid{grid-template-columns:1fr 1fr}.hero{flex-direction:column}}@media(max-width:480px){.grid{grid-template-columns:1fr}}
