<div class="panel"><div class="hero"><div><h2>Patient identity</h2><p class="muted">Registered at CityCare Medical Center.</p></div><span class="badge">{{ ucfirst($patient->status) }}</span></div><div class="grid"><div class="item"><label>Full name</label><strong>{{ $patient->full_name }}</strong></div><div class="item"><label>Sex</label><strong>{{ $patient->sex ?: 'Not recorded' }}</strong></div><div class="item"><label>Date of birth</label><strong>{{ $patient->date_of_birth?->format('d M Y') ?: 'Not recorded' }}</strong></div><div class="item"><label>National ID</label><strong>{{ $patient->national_id ?: 'Not recorded' }}</strong></div><div class="item"><label>Phone</label><strong>{{ $patient->phone ?: 'Not recorded' }}</strong></div><div class="item"><label>Email</label><strong>{{ $patient->email ?: 'Not recorded' }}</strong></div></div></div>
<div class="panel"><h2>Contact & next of kin</h2><div class="grid"><div class="item"><label>Address</label><strong>{{ collect([$patient->address_line1,$patient->address_line2,$patient->city,$patient->district])->filter()->implode(', ') ?: 'Not recorded' }}</strong></div><div class="item"><label>Emergency contact</label><strong>{{ $patient->emergency_contact_name ?: 'Not recorded' }}{{ $patient->emergency_contact_relationship ? ' · '.$patient->emergency_contact_relationship : '' }}</strong></div><div class="item"><label>Emergency phone</label><strong>{{ $patient->emergency_contact_phone ?: 'Not recorded' }}</strong></div><div class="item"><label>Next of kin</label><strong>{{ $patient->next_of_kin_name ?: 'Not recorded' }}{{ $patient->next_of_kin_relationship ? ' · '.$patient->next_of_kin_relationship : '' }}</strong></div><div class="item"><label>Next of kin phone</label><strong>{{ $patient->next_of_kin_phone ?: 'Not recorded' }}</strong></div><div class="item"><label>Registered</label><strong>{{ $patient->registered_at?->format('d M Y H:i') ?: 'Not recorded' }}</strong></div></div></div></main></body></html>
